"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[473],{87073:e=>{e.exports=JSON.parse('{"functions":[{"name":"PlaySFX","desc":"Plays a sound effect and returns the [Sound] instance playing it.\\n\\n`soundPath` may be a path relative to `ReplicatedStorage.Assets.Sounds`, a key in\\nthe shared Sounds data table, or a raw `rbxassetid://` id. Returns `nil` when the\\npath resolves to nothing, so a missing asset is not fatal.\\n\\nA non-looping sound destroys itself on `Ended`. Nothing else needs cleaning up.\\n\\n:::caution A looped sound needs a lifetime\\nSetting `looped` without `lifetime` leaves the sound playing forever, since the\\n`Ended` cleanup never fires. Either set a `lifetime`, or keep the returned Sound\\nand stop or destroy it yourself.\\n:::\\n\\n```lua\\nPlaySFX(\\"UI.Click\\")\\nPlaySFX(\\"Impact.Wood\\", { position = hit.Position, pitch = 0.9 })\\n\\nlocal ambience = PlaySFX(\\"Ambient.Cave\\", { looped = true, tweenInTime = 2 })\\n-- later\\nambience:Destroy()\\n```","params":[{"name":"soundPath","desc":"Path to the sound, relative to `ReplicatedStorage.Assets.Sounds`","lua_type":"string"},{"name":"config","desc":"Configuration for the sound effect","lua_type":"SFXConfig?"}],"returns":[{"desc":"The playing sound, or nil if the path did not resolve","lua_type":"Sound?"}],"function_type":"static","source":{"line":91,"path":"src/Shared/Class/PlaySFX.luau"}}],"properties":[],"types":[{"name":"SFXConfig","desc":"Options for one playback. `tweenInTime` also falls back to a `TweenInTime`\\nattribute on the source sound, so a fade can be authored on the asset instead of\\nat every call site.\\n\\nSupplying `position` makes the sound 3D: an anchored, invisible part is created in\\n[Workspace] to emit from and destroyed when the sound ends.","fields":[{"name":"volume","lua_type":"number?","desc":"Target volume; the fade-in destination when `tweenInTime` is set"},{"name":"pitch","lua_type":"number?","desc":"Sets `PlaybackSpeed`"},{"name":"parent","lua_type":"any","desc":"Instance to parent the sound to; defaults to SoundService"},{"name":"lifetime","lua_type":"number?","desc":"Seconds before the sound is destroyed regardless of state"},{"name":"looped","lua_type":"boolean?","desc":"Loop playback; pair with `lifetime` so it can stop"},{"name":"position","lua_type":"Vector3?","desc":"Play positionally from an invisible anchor part at this point"},{"name":"tweenInTime","lua_type":"number?","desc":"Seconds to fade up from silence to `volume`"}],"source":{"line":48,"path":"src/Shared/Class/PlaySFX.luau"}}],"name":"PlaySFX","desc":"Plays a sound effect by name, asset id, or random pick from a group.\\n\\nNames are dotted paths resolved under `ReplicatedStorage.Assets.Sounds`, or keys\\ninto the shared `Core.Assets.CoreSounds` table. When the path lands on a [SoundGroup] or\\nFolder rather than a single [Sound], one of its child sounds is picked at random \u2014\\nand the pick avoids immediately repeating the previous one, so a footstep or hit\\nset does not stutter on the same sample.\\n\\nEvery sound plays from a clone and destroys itself when it ends, so callers do not\\nhave to track instances. The one exception is looped playback, which is described\\non [PlaySFX.PlaySFX].\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":19,"path":"src/Shared/Class/PlaySFX.luau"}}')}}]);